This page is mostly working, but I’d fix a few things before calling it production-ready:

- Initial state mismatch:
  - The header badge says “Admin Mode” by default, but `adminMode` is initialized as `false`.
  - That makes the UI misleading. Default should be something like “Guest Mode” or “Staff Mode”.

- Security / XSS risk:
  - Product names are inserted into `innerHTML` in `updateOrderView()`.
  - If these names ever come from user input or a backend, it can become unsafe.
  - Prefer building DOM nodes or sanitizing input.

- “3D Configurator” is mostly a mock:
  - Select options change nothing in the UI.
  - The estimated price is static. You can make it dynamic with a small price formula.

- No persistence:
  - Orders are stored only in memory. Refresh resets everything.
  - If you want a real storefront, use `localStorage` or a backend.

- Hardcoded PIN logic is fine for a demo, but not for real admin/security.
  - Better to have a minimum secure process and separate staff/admin roles.

- Missing accessibility:
  - Buttons and form controls would benefit from proper labels and `aria-*` attributes.

A cleaner, safer version of the relevant JS is below:

```html
<script>
  let currentOrders = JSON.parse(localStorage.getItem('salehOrders') || '[]');
  let adminMode = false;

  function saveOrders() {
    localStorage.setItem('salehOrders', JSON.stringify(currentOrders));
  }

  function switchTab(tabName) {
    document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
    document.querySelectorAll('.tab-btn').forEach(el => {
      el.classList.remove('bg-amber-600', 'text-white', 'shadow');
      el.classList.add('bg-white', 'text-slate-700', 'shadow-sm');
    });

    document.getElementById('tab-' + tabName).classList.remove('hidden');

    const activeBtn = document.getElementById('tabBtn-' + tabName);
    activeBtn.classList.remove('bg-white', 'text-slate-700', 'shadow-sm');
    activeBtn.classList.add('bg-amber-600', 'text-white', 'shadow');
  }

  function addToOrder(itemName, price) {
    currentOrders.push({ name: itemName, price: Number(price) });
    saveOrders();
    alert(itemName + ' تم إضافتها إلى الطلبات!');
    updateOrderView();
  }

  function renderOrderItem(item, index) {
    const container = document.createElement('div');
    container.className = 'flex justify-between items-center p-3 bg-slate-50 rounded-xl border';

    const name = document.createElement('span');
    name.className = 'text-sm font-semibold';
    name.textContent = item.name;

    const right = document.createElement('div');
    right.className = 'flex items-center gap-2';

    const price = document.createElement('span');
    price.className = 'text-amber-600 font-bold';
    price.textContent = 'SAR ' + item.price;

    if (adminMode) {
      const removeBtn = document.createElement('button');
      removeBtn.className = 'text-red-500 hover:text-red-700 text-xs px-2 py-1 bg-red-50 rounded';
      removeBtn.innerHTML = '<i class="fas fa-trash"></i>';
      removeBtn.onclick = () => removeOrder(index);
      right.appendChild(price);
      right.appendChild(removeBtn);
    } else {
      right.appendChild(price);
    }

    container.appendChild(name);
    container.appendChild(right);
    return container;
  }

  function updateOrderView() {
    const listContainer = document.getElementById('orderList');
    const totalContainer = document.getElementById('invoiceTotal');

    if (currentOrders.length === 0) {
      listContainer.innerHTML = '<p class="text-sm text-slate-500">لا توجد طلبات جديدة.</p>';
      totalContainer.classList.add('hidden');
      return;
    }

    listContainer.innerHTML = '';
    let total = 0;

    currentOrders.forEach((item, index) => {
      total += Number(item.price);
      listContainer.appendChild(renderOrderItem(item, index));
    });

    totalContainer.classList.remove('hidden');
    document.getElementById('totalAmount').textContent = 'SAR ' + total;
  }

  function removeOrder(index) {
    currentOrders.splice(index, 1);
    saveOrders();
    updateOrderView();
  }

  function verifyPin() {
    const pin = document.getElementById('pinInput').value.trim();

    if (pin === '1234') {
      alert('تم تسجيل الدخول بنجاح كـ Admin!');
      document.getElementById('roleBadge').innerText = 'Admin Mode';
      adminMode = true;
      updateOrderView();
      switchTab('orders');
    } else if (pin === '0000') {
      alert('تم تسجيل الدخول بنجاح كـ Staff!');
      document.getElementById('roleBadge').innerText = 'Staff Mode';
      adminMode = false;
      updateOrderView();
      switchTab('orders');
    } else {
      alert('PIN غير صحيح! استخدم PIN الصحيح.');
    }
  }

  document.addEventListener('DOMContentLoaded', () => {
    document.getElementById('roleBadge').innerText = 'Guest Mode';
    updateOrderView();
  });
</script>
```

