        <button onclick="switchTab('shop')" id="tabBtn-shop" class="tab-btn px-4 py-2 rounded-xl text-sm font-bold bg-amber-600 text-white shadow">
          <i class="fas fa-store ml-1"></i> 쇼룸 / Products
        </button>
        <button onclick="switchTab('customizer')" id="tabBtn-customizer" class="tab-btn px-4 py-2 rounded-xl text-sm font-bold bg-white text-slate-700 hover:bg-slate-100 shadow-sm">
          <i class="fas fa-couch ml-1"></i> ۳ডি কনফিগুরেটর / 3D Config
        </button>
        <button onclick="switchTab('orders')" id="tabBtn-orders" class="tab-btn px-4 py-2 rounded-xl text-sm font-bold bg-white text-slate-700 hover:bg-slate-100 shadow-sm">
          <i class="fas fa-clipboard-list ml-1"></i> অর্ডার ও ইনভয়েস / Orders
        </button>
        <button onclick="switchTab('admin')" id="tabBtn-admin" class="tab-btn px-4 py-2 rounded-xl text-sm font-bold bg-white text-slate-700 hover:bg-slate-100 shadow-sm">
          <i class="fas fa-shield-alt ml-1"></i> এডমিন প্যানেল / Admin
        </button>
      </div>

      <div id="tab-shop" class="tab-content">
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
