              <h3 class="font-bold text-lg mb-1">Modern Royal Bedroom Set</h3>
              <p class="text-xs text-slate-500 mb-3">King size bed with premium wooden finish.</p>
              <div class="flex justify-between items-center">
                <span class="text-amber-600 font-black text-lg">SAR 4,500</span>
                <button onclick="addToOrder('Modern Royal Bedroom Set', 4500)" class="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-amber-600 transition">অর্ডার করুন</button>
              </div>
            </div>
          </div>

          <div class="bg-white rounded-2xl shadow-md overflow-hidden border border-slate-100">
            <div class="h-48 bg-slate-200 flex items-center justify-center text-slate-500 font-bold text-lg">
              <i class="fas fa-door-closed text-4xl text-amber-600"></i>
            </div>
            <div class="p-4">
              <h3 class="font-bold text-lg mb-1">Custom L-Shaped Wardrobe</h3>
              <p class="text-xs text-slate-500 mb-3">Dark walnut finish with built-in LED lighting.</p>
              <div class="flex justify-between items-center">
                <span class="text-amber-600 font-black text-lg">SAR 3,200</span>
