          <div class="bg-white rounded-2xl shadow-md overflow-hidden border border-slate-100">
            <div class="h-48 bg-slate-200 flex items-center justify-center text-slate-500 font-bold text-lg">
              <i class="fas fa-couch text-4xl text-amber-600"></i>
            </div>
            <div class="p-4">
              <h3 class="font-bold text-lg mb-1">Luxury Sofa Lounge</h3>
              <p class="text-xs text-slate-500 mb-3">Glossy cream comfort seating for modern living room.</p>
              <div class="flex justify-between items-center">
                <span class="text-amber-600 font-black text-lg">SAR 2,800</span>
                <button onclick="addToOrder('Luxury Sofa Lounge', 2800)" class="bg-slate-900 text-white px-3 py-1.5 rounded-lg text-xs font-bold hover:bg-amber-600 transition">অর্ডার করুন</button>
              </div>
            </div>
          </div>
        </div>
      </div>

      <div id="tab-customizer" class="tab-content hidden">
        <div class="bg-white rounded-2xl p-6 shadow-md border border-slate-100 max-w-2xl mx-auto">
          <h3 class="text-xl font-bold mb-4 text-slate-900 border-b pb-2">Interactive 3D Furniture Configurator</h3>

          <div class="space-y-4">
            <div>
              <label class="block text-sm font-semibold mb-1">কাঠের রঙ নির্বাচন করুন / Wood Finish:</label>
              <select id="configWood" class="w-full p-2.5 border rounded-xl bg-slate-50 text-sm">
                <option value="Dark Walnut">Dark Walnut (ডার্ক ওয়ালনাট)</option>
                <option value="Glossy Cream">Glossy Cream (গ্লসি ক্রিম)</option>
                <option value="Natural Oak">Natural Oak (ন্যাচারাল ওক)</option>
              </select>
            </div>

            <div>
              <label class="block text-sm font-semibold mb-1">সাইজ / Size Dimensions:</label>
              <select id="configSize" class="w-full p-2.5 border rounded-xl bg-slate-50 text-sm">
                <option value="200cm x 220cm">200cm x 220cm (Standard)</option>
                <option value="250cm x 220cm">250cm x 220cm (Large)</option>
              </select>
            </div>

            <div class="p-4 bg-amber-50 rounded-xl border border-amber-200 text-center">
              <p class="text-xs text-amber-800 font-semibold">আনুমানিক মূল্য / Estimated Price:</p>
              <span id="configPrice" class="text-2xl font-black text-amber-600">SAR 3,500</span>
            </div>

            <button onclick="submitCustomConfig()" class="w-full bg-amber-600 hover:bg-amber-700 text-white py-3 rounded-xl font-bold text-sm shadow">
              <i class="fab fa-whatsapp ml-1"></i> WhatsApp-এ কোটেশন পাঠান
            </button>
          </div>
        </div>
      </div>

      <div id="tab-orders" class="tab-content hidden">
        <div class="bg-white rounded-2xl p-6 shadow-md border border-slate-100">
          <h3 class="text-xl font-bold mb-4 text-slate-900">Current Order & Invoices</h3>
          <div id="orderList" class="space-y-3 mb-4">
            <p class="text-sm text-slate-500">কোনো নতুন অর্ডার যুক্ত করা হয়নি। শোরুম থেকে পণ্য সিলেক্ট করুন।</p>
          </div>
          <div id="invoiceTotal" class="hidden font-bold text-lg text-right border-t pt-3">
            মোট: <span class="text-amber-600" id="totalAmount">SAR 0</span>
          </div>
        </div>
      </div>

      <div id="tab-admin" class="tab-content hidden">
        <div class="bg-white rounded-2xl p-6 shadow-md border border-slate-100 max-w-md mx-auto text-center">
          <h3 class="text-xl font-bold mb-2">Admin & Staff Security Portal</h3>
          <p class="text-xs text-slate-500 mb-4">মালিক ও স্টাফদের জন্য আলাদা সিকিউরিটি পিন কোড দিয়ে লগইন করুন।</p>
          <div class="space-y-3">
            <input type="password" id="pinInput" placeholder="Enter PIN (Admin: 1234, Staff: 0000)" class="w-full p-3 border rounded-xl text-center text-lg tracking-widest bg-slate-50">
            <button onclick="verifyPin()" class="w-full bg-slate-900 hover:bg-slate-800 text-white py-3 rounded-xl font-bold text-sm">লগইন করুন</button>
          </div>
        </div>
