```js
const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

app.use(cors());
app.use(express.json());

const dataDir = path.join(__dirname, 'data');
const storePath = path.join(dataDir, 'store.json');

function ensureDataFile() {
  if (!fs.existsSync(dataDir)) fs.mkdirSync(dataDir, { recursive: true });
  if (!fs.existsSync(storePath)) {
    const initialData = {
      catalog: [
        { id: 1, name: 'Modern Royal Bedroom Set', price: 4500, description: 'Premium wooden finish • King size', badge: 'Best Seller', icon: 'fa-bed' },
        { id: 2, name: 'Custom L-Shaped Wardrobe', price: 3200, description: 'Walnut finish • LED integrated', badge: 'Custom', icon: 'fa-door-closed' },
        { id: 3, name: 'Luxury Sofa Lounge', price: 2800, description: 'Cream comfort • Modern design', badge: 'New', icon: 'fa-couch' }
      ],
      inventory: [
        { id: 1, name: 'Modern Royal Bedroom Set', stock: 10, price: 4500 },
        { id: 2, name: 'Custom L-Shaped Wardrobe', stock: 16, price: 3200 },
        { id: 3, name: 'Luxury Sofa Lounge', stock: 12, price: 2800 },
        { id: 4, name: 'Luxury Dining Table', stock: 7, price: 6100 },
        { id: 5, name: 'Custom Coffee Table', stock: 18, price: 2200 }
      ],
      orders: []
    };
    fs.writeFileSync(storePath, JSON.stringify(initialData, null, 2));
  }
}

function readStore() {
  ensureDataFile();
  const raw = fs.readFileSync(storePath, 'utf8');
  return JSON.parse(raw);
}

function writeStore(data) {
  fs.writeFileSync(storePath, JSON.stringify(data, null, 2));
}

app.use(express.static(path.join(__dirname, 'public')));

// GET catalog
app.get('/api/catalog', (req, res) => {
  const data = readStore();
  res.json(data.catalog);
});

// GET inventory
app.get('/api/inventory', (req, res) => {
  const data = readStore();
  res.json(data.inventory);
});

// GET orders
app.get('/api/orders', (req, res) => {
  const data = readStore();
  res.json(data.orders);
});

// Login check
app.post('/api/login', (req, res) => {
  const { pin } = req.body || {};
  if (pin === '1234' || pin === '0000') {
    return res.json({ success: true, role: pin === '1234' ? 'admin' : 'staff' });
  }
  return res.status(401).json({ success: false, message: 'Invalid PIN' });
});

// Create new product
app.post('/api/products', (req, res) => {
  const { name, stock, price } = req.body || {};
  if (!name || stock === undefined || price === undefined) {
    return res.status(400).json({ message: 'Missing fields' });
  }

  const store = readStore();
  const product = {
    id: Date.now(),
    name,
    stock: Number(stock),
    price: Number(price)
  };

  store.inventory.push(product);
  store.catalog.push({
    id: product.id,
    name,
    price: Number(price),
    description: 'Custom product',
    badge: 'New',
    icon: 'fa-couch'
  });

  writeStore(store);
  res.json(product);
});

// Update product
app.put('/api/products/:id', (req, res) => {
  const { id } = req.params;
  const { name, stock, price } = req.body || {};

  const store = readStore();
  const inventoryItem = store.inventory.find((item) => String(item.id) === String(id));
  if (!inventoryItem) return res.status(404).json({ message: 'Product not found' });

  inventoryItem.name = name || inventoryItem.name;
  inventoryItem.stock = Number(stock ?? inventoryItem.stock);
  inventoryItem.price = Number(price ?? inventoryItem.price);

  const catalogItem = store.catalog.find((item) => String(item.id) === String(id));
  if (catalogItem) {
    catalogItem.name = inventoryItem.name;
    catalogItem.price = inventoryItem.price;
  }

  writeStore(store);
  res.json(inventoryItem);
});

// Delete product
app.delete('/api/products/:id', (req, res) => {
  const { id } = req.params;
  const store = readStore();

  store.inventory = store.inventory.filter((item) => String(item.id) !== String(id));
  store.catalog = store.catalog.filter((item) => String(item.id) !== String(id));

  writeStore(store);
  res.json({ success: true });
});

// Create order
app.post('/api/orders', (req, res) => {
  const { customerName, customerPhone, customerCity, customerNotes, items } = req.body || {};
  if (!customerName || !customerPhone || !customerCity || !Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ message: 'Missing checkout data' });
  }

  const store = readStore();
  const order = {
    id: Date.now(),
    customerName,
    customerPhone,
    customerCity,
    customerNotes: customerNotes || '',
    items,
    total: items.reduce((sum, item) => sum + Number(item.price || 0), 0),
    createdAt: new Date().toISOString()
  };

  store.orders.push(order);
  writeStore(store);

  res.json(order);
});

app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Saleh Furniture backend running on http://localhost:${PORT}`);
});
