const state = {
  catalog: [],
  cart: [],
  adminMode: false
};

async function apiFetch(url, options = {}) {
  const res = await fetch(url, {
    headers: { 'Content-Type': 'application/json' },
    ...options
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({ message: 'Request failed' }));
    throw new Error(err.message || 'Request failed');
  }

  return res.json();
}

async function loadCatalog() {
  state.catalog = await apiFetch('/api/catalog');
  renderCatalog();
}

function renderCatalog() {
  const grid = document.getElementById('catalogGrid');
  grid.innerHTML = '';

  state.catalog.forEach((product) => {
    const card = document.createElement('article');
    card.className = 'luxury-card rounded-[26px] overflow-hidden';

    card.innerHTML = `
      <div class="product-image h-56 flex items-center justify-center">
        <i class="fas ${product.icon} text-5xl text-amber-600"></i>
      </div>
      <div class="p-5">
        <div class="flex justify-between items-start gap-3">
          <div>
            <h4 class="font-black text-xl">${product.name}</h4>
            <p class="text-xs text-slate-500">${product.description}</p>
          </div>
          <span class="bg-amber-50 text-amber-700 px-2 py-1 rounded-full text-[10px] font-bold">${product.badge}</span>
        </div>
        <div class="mt-5 flex justify-between items-center">
          <span class="text-amber-600 font-black text-2xl">SAR ${Number(product.price).toLocaleString()}</span>
          <button onclick="addToOrder('${product.name}', ${product.price})" class="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold">অর্ডার করুন</button>
        </div>
      </div>
    `;

    grid.appendChild(card);
  });
}

function switchTab(tabName) {
  document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById('tab-' + tabName).classList.remove('hidden');
  document.getElementById('tabBtn-' + tabName).classList.add('active');
}

function addToOrder(name, price) {
  state.cart.push({ name, price: Number(price) });
  updateOrderView();
}

function updateOrderView() {
  const listContainer = document.getElementById('orderList');
  const totalContainer = document.getElementById('invoiceTotal');

  if (state.cart.length === 0) {
    listContainer.innerHTML = '<p class="text-sm text-slate-500">No new orders yet.</p>';
    totalContainer.classList.add('hidden');
    return;
  }

  let html = '';
  let total = 0;

  state.cart.forEach((item) => {
    total += Number(item.price);
    html += `
      <div class="flex justify-between items-center p-3 bg-slate-50 rounded-xl border">
        <span class="text-sm font-semibold">${item.name}</span>
        <span class="text-amber-600 font-bold">SAR ${Number(item.price).toLocaleString()}</span>
      </div>
    `;
  });

  listContainer.innerHTML = html;
  totalContainer.classList.remove('hidden');
  document.getElementById('totalAmount').textContent = 'SAR ' + total.toLocaleString();
}

function calculateConfigPrice() {
  const wood = document.getElementById('configWood').value;
  const size = document.getElementById('configSize').value;
  let base = 3000;

  if (wood === 'Dark Walnut') base += 450;
  if (wood === 'Glossy Cream') base += 300;
  if (wood === 'Natural Oak') base += 520;
  if (size === '250cm x 220cm') base += 700;

  document.getElementById('configPrice').textContent = 'SAR ' + base.toLocaleString();
  return base;
}

function submitCustomConfig() {
  const wood = document.getElementById('configWood').value;
  const size = document.getElementById('configSize').value;
  const price = calculateConfigPrice();

  const name = `Custom Configuration (${wood} / ${size})`;
  addToOrder(name, price);

  const msg = encodeURIComponent(`Hello Saleh Furniture,\nCustom Configuration:\n- Finish: ${wood}\n- Size: ${size}\n- Price: SAR ${price.toLocaleString()}\nPlease send quote.`);
  window.open(`https://wa.me/966500000000?text=${msg}`, '_blank');
}

async function submitCheckout() {
  if (state.cart.length === 0) {
    alert('Please add at least one product.');
    return;
  }

  const customerName = document.getElementById('customerName').value.trim();
  const phone = document.getElementById('customerPhone').value.trim();
  const city = document.getElementById('customerCity').value.trim();
  const notes = document.getElementById('customerNotes').value.trim();

  if (!customerName || !phone || !city) {
    alert('Please fill Name, Phone, City.');
    return;
  }

  try {
    const payload = {
      customerName,
      customerPhone: phone,
      customerCity: city,
      customerNotes: notes,
      items: state.cart
    };

    const result = await apiFetch('/api/orders', {
      method: 'POST',
      body: JSON.stringify(payload)
    });

    let message = `Hello Saleh Furniture,\n\nNew Order Request\nCustomer Name: ${customerName}\nPhone: ${phone}\nCity: ${city}\nNotes: ${notes || 'N/A'}\n\nItems:\n`;

    result.items.forEach((item, index) => {
      message += `${index + 1}. ${item.name} - SAR ${Number(item.price).toLocaleString()}\n`;
    });

    message += `\nTotal: SAR ${Number(result.total).toLocaleString()}`;

    state.cart = [];
    updateOrderView();

    window.open(`https://wa.me/966500000000?text=${encodeURIComponent(message)}`, '_blank');
  } catch (error) {
    alert(error.message);
  }
}

async function verifyPin() {
  const pin = document.getElementById('pinInput').value.trim();

  try {
    const result = await apiFetch('/api/login', {
      method: 'POST',
      body: JSON.stringify({ pin })
    });

    if (result.success) {
      state.adminMode = result.role === 'admin';
      document.getElementById('roleBadge').innerText = result.role === 'admin' ? 'Admin Mode' : 'Staff Mode';
      switchTab('orders');
      alert(result.role === 'admin' ? 'Admin Login successful!' : 'Staff Login successful!');
    }
  } catch (error) {
    alert(error.message);
  }
}

document.addEventListener('DOMContentLoaded', async () => {
  await loadCatalog();
  document.getElementById('configWood').addEventListener('change', calculateConfigPrice);
  document.getElementById('configSize').addEventListener('change', calculateConfigPrice);
  calculateConfigPrice();
  updateOrderView();
});
