```js
const state = {
  catalog: [],
  inventory: [],
  orders: [],
  cart: [],
  adminMode: false,
  editingId: null
};

async function apiFetch(url, options = {}) {
  const response = await fetch(url, {
    headers: { 'Content-Type': 'application/json' },
    ...options
  });

  if (!response.ok) {
    const err = await response.json().catch(() => ({ message: 'Request failed' }));
    throw new Error(err.message || 'Request failed');
  }

  return response.json();
}

async function loadCatalog() {
  state.catalog = await apiFetch('/api/catalog');
  renderCatalog();
}

async function loadInventory() {
  state.inventory = await apiFetch('/api/inventory');
  renderInventoryTable();
  updateDashboard();
}

async function loadOrders() {
  state.orders = await apiFetch('/api/orders');
  renderRecentOrders();
  updateDashboard();
}

function renderCatalog() {
  const grid = document.getElementById('catalogGrid');
  grid.innerHTML = '';

  state.catalog.forEach((product) => {
    const card = document.createElement('article');
    card.className = 'luxury-card rounded-[26px] overflow-hidden';

    card.innerHTML = `
      <div class="product-image h-56 flex items-center justify-center">
        <i class="fas ${product.icon} text-5xl text-amber-600"></i>
      </div>
      <div class="p-5">
        <div class="flex justify-between items-start gap-3">
          <div>
            <h4 class="font-black text-xl">${product.name}</h4>
            <p class="text-xs text-slate-500">${product.description}</p>
          </div>
          <span class="bg-amber-50 text-amber-700 px-2 py-1 rounded-full text-[10px] font-bold">${product.badge}</span>
        </div>
        <div class="mt-5 flex justify-between items-center">
          <span class="text-amber-600 font-black text-2xl">SAR ${Number(product.price).toLocaleString()}</span>
          <button onclick="addToOrder('${product.name}', ${product.price})" class="bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold">অর্ডার করুন</button>
        </div>
      </div>
    `;

    grid.appendChild(card);
  });
}

function switchTab(tabName) {
  document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));
  document.querySelectorAll('.tab-btn').forEach(el => el.classList.remove('active'));
  document.getElementById('tab-' + tabName).classList.remove('hidden');
  document.getElementById('tabBtn-' + tabName).classList.add('active');
}

function addToOrder(name, price) {
  state.cart.push({ name, price: Number(price) });
  updateOrderView();
}

function updateOrderView() {
  const listContainer = document.getElementById('orderList');
  const totalContainer = document.getElementById('invoiceTotal');

  if (state.cart.length === 0) {
    listContainer.innerHTML = '<p class="text-sm text-slate-500">No new orders yet.</p>';
    totalContainer.classList.add('hidden');
    return;
  }

  let html = '';
  let total = 0;

  state.cart.forEach((item, index) => {
    total += Number(item.price);

    html += `
      <div class="flex justify-between items-center p-3 bg-slate-50 rounded-xl border">
        <span class="text-sm font-semibold">${item.name}</span>
        <div class="flex items-center gap-3">
          <span class="text-amber-600 font-bold">SAR ${Number(item.price).toLocaleString()}</span>
          ${state.adminMode ? `<button onclick="removeOrder(${index})" class="text-red-500 hover:text-red-700 text-xs px-2 py-1 bg-red-50 rounded"><i class="fas fa-trash"></i></button>` : ''}
        </div>
      </div>
    `;
  });

  listContainer.innerHTML = html;
  totalContainer.classList.remove('hidden');
  document.getElementById('totalAmount').textContent = 'SAR ' + total.toLocaleString();
}

function removeOrder(index) {
  state.cart.splice(index, 1);
  updateOrderView();
}

function calculateConfigPrice() {
  const wood = document.getElementById('configWood').value;
  const size = document.getElementById('configSize').value;
  let base = 3000;

  if (wood === 'Dark Walnut') base += 450;
  if (wood === 'Glossy Cream') base += 300;
  if (wood === 'Natural Oak') base += 520;
  if (size === '250cm x 220cm') base += 700;

  document.getElementById('configPrice').textContent = 'SAR ' + base.toLocaleString();
  return base;
}

function submitCustomConfig() {
  const wood = document.getElementById('configWood').value;
  const size = document.getElementById('configSize').value;
  const price = calculateConfigPrice();

  const name = `Custom Configuration (${wood} / ${size})`;
  addToOrder(name, price);

  const msg = encodeURIComponent(`Hello Saleh Furniture,\nCustom Configuration:\n- Finish: ${wood}\n- Size: ${size}\n- Price: SAR ${price.toLocaleString()}\nPlease send quote.`);
  window.open(`https://wa.me/966500000000?text=${msg}`, '_blank');
}

async function submitCheckout() {
  if (state.cart.length === 0) {
    alert('Please add at least one product.');
    return;
  }

  const customerName = document.getElementById('customerName').value.trim();
  const phone = document.getElementById('customerPhone').value.trim();
  const city = document.getElementById('customerCity').value.trim();
  const notes = document.getElementById('customerNotes').value.trim();

  if (!customerName || !phone || !city) {
    alert('Please fill Name, Phone, City.');
    return;
  }

  try {
    const result = await apiFetch('/api/orders', {
      method: 'POST',
      body: JSON.stringify({
        customerName,
        customerPhone: phone,
        customerCity: city,
        customerNotes: notes,
        items: state.cart
      })
    });

    let message = `Hello Saleh Furniture,\n\nNew Order Request\nCustomer Name: ${customerName}\nPhone: ${phone}\nCity: ${city}\nNotes: ${notes || 'N/A'}\n\nItems:\n`;

    result.items.forEach((item, index) => {
      message += `${index + 1}. ${item.name} - SAR ${Number(item.price).toLocaleString()}\n`;
    });

    message += `\nTotal: SAR ${Number(result.total).toLocaleString()}`;

    state.cart = [];
    updateOrderView();

    window.open(`https://wa.me/966500000000?text=${encodeURIComponent(message)}`, '_blank');
    await loadOrders();
  } catch (error) {
    alert(error.message);
  }
}

async function verifyPin() {
  const pin = document.getElementById('pinInput').value.trim();

  try {
    const result = await apiFetch('/api/login', {
      method: 'POST',
      body: JSON.stringify({ pin })
    });

    if (result.success) {
      state.adminMode = result.role === 'admin';
      document.getElementById('roleBadge').innerText = result.role === 'admin' ? 'Admin Mode' : 'Staff Mode';
      document.getElementById('adminLoginPanel').classList.add('hidden');
      document.getElementById('adminDashboard').classList.remove('hidden');
      switchTab('orders');
      updateOrderView();
      updateDashboard();
    }
  } catch (error) {
    alert(error.message);
  }
}

function renderInventoryTable() {
  const tbody = document.getElementById('inventoryTable');
  tbody.innerHTML = '';

  state.inventory.forEach(item => {
    const row = document.createElement('tr');
    row.innerHTML = `
      <td class="py-2 text-right">${item.name}</td>
      <td class="py-2 text-right">${item.stock}</td>
      <td class="py-2 text-right">SAR ${Number(item.price).toLocaleString()}</td>
      <td class="py-2 text-right">
        <div class="flex justify-end gap-2">
          <button onclick="editProduct(${item.id})" class="text-blue-600 hover:text-blue-800"><i class="fas fa-edit"></i></button>
          <button onclick="deleteProduct(${item.id})" class="text-red-500 hover:text-red-700"><i class="fas fa-trash"></i></button>
        </div>
      </td>
    `;
    tbody.appendChild(row);
  });
}

function renderRecentOrders() {
  const wrap = document.getElementById('recentOrdersList');
  wrap.innerHTML = '';

  if (state.orders.length === 0) {
    wrap.innerHTML = '<p class="text-sm text-slate-500">No recent orders.</p>';
    return;
  }

  state.orders.slice(0, 5).forEach(order => {
    const item = document.createElement('div');
    item.className = 'p-3 bg-slate-50 rounded-xl border border-slate-200';
    item.innerHTML = `
      <div class="flex justify-between items-center">
        <span class="font-semibold text-sm">${order.customerName}</span>
        <span class="text-amber-600 font-bold text-sm">SAR ${Number(order.total).toLocaleString()}</span>
      </div>
      <div class="mt-1 text-xs text-slate-500">${order.items.length} items</div>
    `;
    wrap.appendChild(item);
  });
}

function updateDashboard() {
  const totalSales = state.orders.reduce((sum, order) => sum + Number(order.total || 0), 0);
  const ordersCount = state.orders.length;
  const inventoryCount = state.inventory.reduce((sum, item) => sum + Number(item.stock || 0), 0);

  document.getElementById('totalSalesValue').textContent = totalSales.toLocaleString();
  document.getElementById('ordersCountValue').textContent = ordersCount;
  document.getElementById('inventoryCountValue').textContent = inventoryCount;

  renderInventoryTable();
  renderRecentOrders();
}

function showAddProductModal() {
  state.editingId = null;
  document.getElementById('modalProductName').value = '';
  document.getElementById('modalProductStock').value = '';
  document.getElementById('modalProductPrice').value = '';
  document.getElementById('productModal').classList.remove('hidden');
  document.getElementById('productModal').classList.add('flex');
}

function closeProductModal() {
  document.getElementById('productModal').classList.add('hidden');
  document.getElementById('productModal').classList.remove('flex');
}

function editProduct(id) {
  const product = state.inventory.find(item => item.id === id);
  if (!product) return;

  state.editingId = id;
  document.getElementById('modalProductName').value = product.name;
  document.getElementById('modalProductStock').value = product.stock;
  document.getElementById('modalProductPrice').value = product.price;

  document.getElementById('productModal').classList.remove('hidden');
  document.getElementById('productModal').classList.add('flex');
}

async function saveProduct() {
  const name = document.getElementById('modalProductName').value.trim();
  const stock = Number(document.getElementById('modalProductStock').value);
  const price = Number(document.getElementById('modalProductPrice').value);

  if (!name || !Number.isFinite(stock) || !Number.isFinite(price)) {
    alert('Please fill valid values.');
    return;
  }

  try {
    if (state.editingId === null) {
      await apiFetch('/api/products', {
        method: 'POST',
        body: JSON.stringify({ name, stock, price })
      });
    } else {
      await apiFetch(`/api/products/${state.editingId}`, {
        method: 'PUT',
        body: JSON.stringify({ name, stock, price })
      });
    }

    await loadInventory();
    await loadCatalog();
    closeProductModal();
  } catch (error) {
    alert(error.message);
  }
}

async function deleteProduct(id) {
  try {
    await apiFetch(`/api/products/${id}`, { method: 'DELETE' });
    await loadInventory();
    await loadCatalog();
  } catch (error) {
    alert(error.message);
  }
}

function clearOrders() {
  state.orders = [];
  updateDashboard();
}

document.addEventListener('DOMContentLoaded', async () => {
  await loadCatalog();
  await loadInventory();
  await loadOrders();

  document.getElementById('configWood').addEventListener('change', calculateConfigPrice);
  document.getElementById('configSize').addEventListener('change', calculateConfigPrice);

  calculateConfigPrice();
  updateOrderView();
  updateDashboard();
});
