      loadInventory();
      loadCatalog();
    } catch (error) {
      alert(error.message);
    }
  };

  const clearOrders = () => {
    setOrders([]);
  };

  const totalCart = cart.reduce((sum, item) => sum + item.price, 0);

  return (
    <div className="min-h-screen flex flex-col">
