              </div>
            </div>
          </div>
        </div>
      )}

      <footer className="bg-slate-900 text-white py-5 text-center text-xs text-slate-400">
        © 2026 Saleh Furniture. Riyadh, KSA.
      </footer>
    </div>
  );
}

export default App;
