import { useEffect, useState } from 'react';

const initialProducts = [
  { id: 1, name: 'Modern Royal Bedroom Set', price: 4500, description: 'Premium wooden finish • King size', badge: 'Best Seller', icon: 'fa-bed' },
  { id: 2, name: 'Custom L-Shaped Wardrobe', price: 3200, description: 'Walnut finish • LED integrated', badge: 'Custom', icon: 'fa-door-closed' },
  { id: 3, name: 'Luxury Sofa Lounge', price: 2800, description: 'Cream comfort • Modern design', badge: 'New', icon: 'fa-couch' }
];

const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:3000';

async function apiFetch(url, options = {}) {
  const response = await fetch(`${API_URL}${url}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options
  });

  if (!response.ok) {
    const err = await response.json().catch(() => ({ message: 'Request failed' }));
    throw new Error(err.message || 'Request failed');
  }

  return response.json();
}

function App() {
  const [catalog, setCatalog] = useState(initialProducts);
  const [inventory, setInventory] = useState([]);
  const [orders, setOrders] = useState([]);
  const [cart, setCart] = useState([]);
  const [activeTab, setActiveTab] = useState('shop');
  const [role, setRole] = useState('Guest');
  const [adminOpen, setAdminOpen] = useState(false);
  const [pin, setPin] = useState('');
  const [modalOpen, setModalOpen] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [formProduct, setFormProduct] = useState({ name: '', stock: '', price: '' });

  const [configWood, setConfigWood] = useState('Dark Walnut');
  const [configSize, setConfigSize] = useState('200cm x 220cm');

  useEffect(() => {
    loadCatalog();
    loadInventory();
    loadOrders();
  }, []);

  const loadCatalog = async () => {
    try {
      const data = await apiFetch('/api/catalog');
      setCatalog(data);
    } catch (err) {
      setCatalog(initialProducts);
    }
  };

  const loadInventory = async () => {
    try {
      const data = await apiFetch('/api/inventory');
      setInventory(data);
    } catch (err) {
      setInventory([]);
    }
  };

  const loadOrders = async () => {
    try {
      const data = await apiFetch('/api/orders');
      setOrders(data);
    } catch (err) {
      setOrders([]);
    }
  };

  const addToCart = (name, price) => {
    setCart(prev => [...prev, { name, price: Number(price) }]);
  };

  const removeCartItem = (index) => {
    setCart(prev => prev.filter((_, i) => i !== index));
  };

  const calculateConfigPrice = () => {
    let base = 3000;
    if (configWood === 'Dark Walnut') base += 450;
    if (configWood === 'Glossy Cream') base += 300;
    if (configWood === 'Natural Oak') base += 520;
    if (configSize === '250cm x 220cm') base += 700;
    return base;
  };

  const submitCustomConfig = () => {
    const price = calculateConfigPrice();
    const itemName = `Custom Configuration (${configWood} / ${configSize})`;
    addToCart(itemName, price);

    const msg = encodeURIComponent(
      `Hello Saleh Furniture,\nI would like a custom configuration:\n- Finish: ${configWood}\n- Size: ${configSize}\n- Estimated Price: SAR ${price.toLocaleString()}\nPlease send me a quote on WhatsApp.`
    );
    window.open(`https://wa.me/966500000000?text=${msg}`, '_blank');
  };

  const submitCheckout = async () => {
    if (!cart.length) {
      alert('Please add at least one product.');
      return;
    }

    const customerName = document.getElementById('customerName')?.value.trim();
    const customerPhone = document.getElementById('customerPhone')?.value.trim();
    const customerCity = document.getElementById('customerCity')?.value.trim();
    const customerNotes = document.getElementById('customerNotes')?.value.trim();

    if (!customerName || !customerPhone || !customerCity) {
      alert('Please fill Name, Phone Number, and City.');
      return;
    }

    try {
      const result = await apiFetch('/api/orders/create', {
        method: 'POST',
        body: JSON.stringify({
          customerName,
          customerPhone,
          customerCity,
          customerNotes,
          items: cart
        })
      });

      let msg = `Hello Saleh Furniture,\n\nNew Order Request\nCustomer Name: ${customerName}\nPhone: ${customerPhone}\nCity: ${customerCity}\nNotes: ${customerNotes || 'N/A'}\n\nItems:\n`;

      result.items.forEach((item, idx) => {
        msg += `${idx + 1}. ${item.name} - SAR ${Number(item.price).toLocaleString()}\n`;
      });

      msg += `\nTotal: SAR ${Number(result.total).toLocaleString()}`;

      window.open(`https://wa.me/966500000000?text=${encodeURIComponent(msg)}`, '_blank');
      setCart([]);
      loadOrders();
    } catch (error) {
      alert(error.message);
    }
  };

  const verifyPin = async () => {
    try {
      const result = await apiFetch('/api/login', {
        method: 'POST',
        body: JSON.stringify({ pin })
      });

      if (result.success) {
        setRole(result.role === 'admin' ? 'Admin' : 'Staff');
        setAdminOpen(true);
        setActiveTab('orders');
      }
    } catch (error) {
      alert(error.message);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setFormProduct({ name: '', stock: '', price: '' });
    setModalOpen(true);
  };

  const openEditModal = (product) => {
    setEditingId(product.id);
    setFormProduct({ name: product.name, stock: product.stock, price: product.price });
    setModalOpen(true);
  };

  const saveProduct = async () => {
    if (!formProduct.name || !formProduct.stock || !formProduct.price) {
      alert('Please fill product name, stock, and price.');
      return;
    }

    try {
      if (editingId) {
        await apiFetch(`/api/products/${editingId}`, {
          method: 'PUT',
          body: JSON.stringify({
            name: formProduct.name,
            stock: Number(formProduct.stock),
            price: Number(formProduct.price)
          })
        });
      } else {
        await apiFetch('/api/products', {
          method: 'POST',
          body: JSON.stringify({
            name: formProduct.name,
            stock: Number(formProduct.stock),
            price: Number(formProduct.price)
          })
        });
      }

      setModalOpen(false);
      loadInventory();
      loadCatalog();
    } catch (error) {
      alert(error.message);
    }
  };

  const deleteProduct = async (id) => {
    try {
      await apiFetch(`/api/products/${id}`, { method: 'DELETE' });
      loadInventory();
      loadCatalog();
    } catch (error) {
      alert(error.message);
    }
  };

  const clearOrders = () => {
    setOrders([]);
  };

  const totalCart = cart.reduce((sum, item) => sum + item.price, 0);

  return (
    <div className="min-h-screen flex flex-col">
      <header className="bg-slate-900 text-white sticky top-0 z-50 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 py-3 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-full bg-amber-500 flex items-center justify-center text-slate-900 font-black text-lg">SF</div>
            <div>
              <h1 className="text-lg font-black">Saleh Furniture</h1>
              <p className="text-[10px] text-amber-400">ساحة فرنيتشير • الرياض</p>
            </div>
          </div>

          <div className="flex items-center gap-2">
            <span className="bg-amber-500 text-slate-900 text-[10px] px-3 py-1 rounded-full font-bold">{role} Mode</span>
            <a href="https://wa.me/966500000000" target="_blank" className="bg-green-600 px-3 py-2 rounded-xl text-xs font-bold">WhatsApp</a>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto w-full px-4 py-6">
        <section className="rounded-3xl p-6 text-white hero-shimmer mb-8">
          <h2 className="text-3xl md:text-5xl font-black">أهلاً بكم في Saleh Furniture</h2>
          <p className="mt-2 text-amber-100">Luxury Custom Furniture & Modern Showroom in Riyadh</p>
        </section>

        <div className="flex gap-2 overflow-x-auto mb-6">
          <button onClick={() => setActiveTab('shop')} className={`tab-btn ${activeTab === 'shop' ? 'active' : ''} px-4 py-2 rounded-xl text-sm font-bold`}>쇼룸 / Products</button>
          <button onClick={() => setActiveTab('customizer')} className={`tab-btn ${activeTab === 'customizer' ? 'active' : ''} px-4 py-2 rounded-xl text-sm font-bold`}>۳ডি কনফিগুরেটর / 3D Config</button>
          <button onClick={() => setActiveTab('orders')} className={`tab-btn ${activeTab === 'orders' ? 'active' : ''} px-4 py-2 rounded-xl text-sm font-bold`}>অর্ডার ও ইনভয়েস / Orders</button>
          <button onClick={() => setActiveTab('admin')} className={`tab-btn ${activeTab === 'admin' ? 'active' : ''} px-4 py-2 rounded-xl text-sm font-bold`}>এডমিন প্যানেল / Admin</button>
        </div>

        {activeTab === 'shop' && (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
            {catalog.map(product => (
              <div key={product.id} className="luxury-card rounded-[26px] overflow-hidden">
                <div className="product-image h-56 flex items-center justify-center">
                  <i className={`fas ${product.icon} text-5xl text-amber-600`}></i>
