                <select value={configSize} onChange={(e) => setConfigSize(e.target.value)} className="w-full p-3 border rounded-xl bg-slate-50">
                  <option value="200cm x 220cm">200cm x 220cm</option>
                  <option value="250cm x 220cm">250cm x 220cm</option>
                </select>
              </div>
              <div className="bg-amber-50 rounded-2xl p-4 text-center">
                <p className="text-xs text-amber-800 font-bold">Estimated Price</p>
                <div className="text-3xl font-black text-amber-700">SAR {calculateConfigPrice().toLocaleString()}</div>
              </div>
              <button onClick={submitCustomConfig} className="w-full bg-amber-600 text-white py-3 rounded-2xl font-black">
                WhatsApp-এ কোটেশন পাঠান
              </button>
            </div>
          </div>
        )}

        {activeTab === 'orders' && (
          <div className="grid grid-cols-1 xl:grid-cols-[1.3fr_0.7fr] gap-6">
            <div className="luxury-card rounded-[30px] p-6">
              <h3 className="text-2xl font-black mb-4">Current Orders</h3>
              <div className="space-y-3 mb-4">
                {cart.length === 0 ? (
                  <p className="text-sm text-slate-500">No new orders yet.</p>
