require('dotenv').config();
const express = require('express');
const cors = require('cors');
const mongoose = require('mongoose');
const path = require('path');

const Product = require('./models/Product');
const Order = require('./models/Order');

const app = express();
const PORT = process.env.PORT || 3000;

app.use(cors());
app.use(express.json());

mongoose.connect(process.env.MONGO_URI)
  .then(() => console.log('MongoDB connected'))
  .catch(err => console.error('MongoDB connection error:', err.message));

const seedProducts = [
  {
    name: 'Modern Royal Bedroom Set',
    price: 4500,
    stock: 10,
    description: 'Premium wooden finish • King size',
    badge: 'Best Seller',
    icon: 'fa-bed'
  },
  {
    name: 'Custom L-Shaped Wardrobe',
    price: 3200,
    stock: 16,
    description: 'Walnut finish • LED integrated',
    badge: 'Custom',
    icon: 'fa-door-closed'
  },
  {
    name: 'Luxury Sofa Lounge',
    price: 2800,
    stock: 12,
    description: 'Cream comfort • Modern design',
    badge: 'New',
    icon: 'fa-couch'
  }
];

async function seedIfEmpty() {
  const count = await Product.countDocuments();
  if (count === 0) {
    await Product.insertMany(seedProducts);
  }
}

seedIfEmpty();

app.get('/api/catalog', async (req, res) => {
  const products = await Product.find().sort({ createdAt: 1 });
  res.json(products);
});

app.get('/api/inventory', async (req, res) => {
  const products = await Product.find().sort({ createdAt: 1 });
  res.json(products);
});

app.get('/api/orders', async (req, res) => {
  const orders = await Order.find().sort({ createdAt: -1 });
  res.json(orders);
});

app.post('/api/login', (req, res) => {
  const { pin } = req.body || {};
  if (pin === '1234') return res.json({ success: true, role: 'admin' });
  if (pin === '0000') return res.json({ success: true, role: 'staff' });
  return res.status(401).json({ success: false, message: 'Invalid PIN' });
});

app.post('/api/products', async (req, res) => {
  const { name, stock, price } = req.body || {};
  if (!name || stock === undefined || price === undefined) {
    return res.status(400).json({ message: 'Missing fields' });
  }

  const product = await Product.create({
    name,
    stock: Number(stock),
    price: Number(price),
    description: 'Custom product',
    badge: 'New',
    icon: 'fa-couch'
  });

  res.json(product);
});

app.put('/api/products/:id', async (req, res) => {
  const { id } = req.params;
  const { name, stock, price } = req.body || {};

  const product = await Product.findByIdAndUpdate(id, {
    name: name || undefined,
    stock: stock !== undefined ? Number(stock) : undefined,
    price: price !== undefined ? Number(price) : undefined
  }, { new: true });

  if (!product) return res.status(404).json({ message: 'Product not found' });
  res.json(product);
});

app.delete('/api/products/:id', async (req, res) => {
  const { id } = req.params;
  const deleted = await Product.findByIdAndDelete(id);
  if (!deleted) return res.status(404).json({ message: 'Product not found' });
  res.json({ success: true });
});

app.post('/api/orders/create', async (req, res) => {
  const { customerName, customerPhone, customerCity, customerNotes, items } = req.body || {};

  if (!customerName || !customerPhone || !customerCity || !Array.isArray(items) || items.length === 0) {
    return res.status(400).json({ message: 'Invalid order payload' });
  }

  const total = items.reduce((sum, item) => sum + Number(item.price || 0), 0);

  const order = await Order.create({
    customerName,
    customerPhone,
    customerCity,
    customerNotes: customerNotes || '',
    items,
    total
  });

  res.json(order);
});

app.get('*', (req, res) => {
  if (req.path.startsWith('/api')) return res.status(404).json({ message: 'API not found' });
  res.sendFile(path.join(__dirname, '..', 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

